import { COMPOSER_AREAS, host, useValue, useQuery } from '@hermes/plugin-sdk'
import { jsx, jsxs } from 'react/jsx-runtime'
import { useState, useEffect } from 'react'
const HERMES_FRAMES = ["", "", "", "", "", "", "", ""]
const accent = 'var(--ui-accent, currentColor)'
